package greet

// Small consumer-side interface: only the method Greeter needs.
type UserStore interface {
	Name(id string) (string, error)
}

type Greeter struct{ store UserStore }

func New(s UserStore) *Greeter { return &Greeter{store: s} }

func (g *Greeter) Greet(id string) (string, error) {
	name, err := g.store.Name(id) // depends on the seam, not a *sql.DB
	if err != nil {
		return "", err
	}
	return "Hello, " + name, nil
}

