package solution

import (
	"errors"
	"testing"
)

// fakeStore is a stateful fake: it records what was saved so we can assert it.
type fakeStore struct{ saved map[string]string }

func (f *fakeStore) Save(id, name string) error {
	if f.saved == nil {
		f.saved = map[string]string{}
	}
	f.saved[id] = name
	return nil
}

func TestRegister(t *testing.T) {
	t.Run("empty name rejected", func(t *testing.T) {
		_, err := Register(&fakeStore{}, "")
		if !errors.Is(err, ErrEmptyName) {
			t.Fatalf("want ErrEmptyName, got %v", err)
		}
	})
	t.Run("valid name stored", func(t *testing.T) {
		fs := &fakeStore{}
		id, err := Register(fs, "ada")
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if id != "u:ada" {
			t.Errorf("id=%q want u:ada", id)
		}
		if fs.saved["u:ada"] != "ada" {
			t.Errorf("store has %v, want ada under u:ada", fs.saved)
		}
	})
}

