func TestParseRange(t *testing.T) {
	cases := []struct {
		name           string
		in             string
		wantLo, wantHi int
		wantErr        bool
	}{
		{"valid", "3-7", 3, 7, false},
		{"reversed", "7-3", 0, 0, true},
		{"not a number", "a-b", 0, 0, true},
		{"missing high", "1-", 0, 0, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lo, hi, err := ParseRange(tc.in)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("ParseRange(%q) expected error", tc.in)
				}
				return // don't check lo/hi on the error path
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if lo != tc.wantLo || hi != tc.wantHi {
				t.Errorf("ParseRange(%q)=%d,%d want %d,%d", tc.in, lo, hi, tc.wantLo, tc.wantHi)
			}
		})
	}
}

// fakeRepo is a stateful, concurrency-safe fake implementing OrderRepo.
type fakeRepo struct {
	mu      sync.Mutex
	orders  map[string]Order
	failGet error // when non-nil, Get returns this error
}

func newFakeRepo() *fakeRepo {
	return &fakeRepo{orders: make(map[string]Order)}
}

func (f *fakeRepo) Save(ctx context.Context, o Order) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.orders[o.ID] = o // record real state, not a canned value
	return nil
}

func (f *fakeRepo) Get(ctx context.Context, id string) (Order, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failGet != nil {
		return Order{}, f.failGet // simulate an injected dependency failure
	}
	o, ok := f.orders[id]
	if !ok {
		return Order{}, fmt.Errorf("order %q: %w", id, ErrNotFound)
	}
	return o, nil
}

func TestServiceGetOrder(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name    string
		seed    *Order
		failGet error
		lookup  string
		wantErr bool
	}{
		{"found", &Order{ID: "o1", Total: 500}, nil, "o1", false},
		{"missing", nil, nil, "nope", true},
		{"repo down", &Order{ID: "o1"}, errors.New("db unavailable"), "o1", true},
	}
	for _, tc := range cases {
		tc := tc // per-iteration copy for pre-1.22 parallel safety
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			repo := newFakeRepo()
			if tc.seed != nil {
				if err := repo.Save(context.Background(), *tc.seed); err != nil {
					t.Fatalf("seed save: %v", err)
				}
			}
			repo.failGet = tc.failGet
			svc := NewService(repo) // inject the fake through the seam

			got, err := svc.GetOrder(context.Background(), tc.lookup)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("GetOrder(%q): expected error", tc.lookup)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got.ID != tc.seed.ID { // assert the outcome, not the call
				t.Errorf("GetOrder(%q).ID = %q, want %q", tc.lookup, got.ID, tc.seed.ID)
			}
		})
	}
}
